import{_ as n,a0 as o,w as m,s as p,I as e,x as a,a1 as i,A as s,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"KDE Plasma 5.23 的新功能和发布日期 | LCTT x X-CMD","titleTemplate":false,"description":"KDE Plasma 5.23 的新功能和发布日期 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"KDE Plasma 5.23 的新功能和发布日期 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"KDE Plasma 5.23 的新功能和发布日期 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210823 KDE Plasma 5.23 - New Features and Release Dates","title":"KDE Plasma 5.23 的新功能和发布日期","tag":"202108","desc":""},"relativePath":"202108/20210823 KDE Plasma 5.23 - New Features and Release Dates.md","filePath":"[post].md"}'),d={name:"202108/20210823 KDE Plasma 5.23 - New Features and Release Dates.md"};function u(f,l,w,D,P,K){const t=o("Link");return m(),p("div",null,[l[19]||(l[19]=e("h1",{id:"kde-plasma-5-23-的新功能和发布日期",tabindex:"-1"},[a("KDE Plasma 5.23 的新功能和发布日期 "),e("a",{class:"header-anchor",href:"#kde-plasma-5-23-的新功能和发布日期","aria-label":"Permalink to “KDE Plasma 5.23 的新功能和发布日期”"},"​")],-1)),l[20]||(l[20]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/25/222802zwhmvv1vwzusevzw.jpg",alt:""})],-1)),l[21]||(l[21]=e("blockquote",null,[e("p",null,"我们在这篇文章中总结了 KDE Plasma 5.23（即将到来）的新功能，包括主要特点、下载和 测试说明。")],-1)),e("p",null,[l[1]||(l[1]=a("KDE Plasma 桌面是当今最流行、最顶级的 Linux 桌面环境，而 KDE Plasma 的热度之高主要得益于其适应能力强、迭代发展迅速，以及性能不断提高。",-1)),i(t,{href:"https://www.debugpoint.com/2021/06/kde-plasma-5-22-release/"},{default:s(()=>[...l[0]||(l[0]=[a("KDE Plasma 5.22",-1)])]),_:1}),l[2]||(l[2]=a(" 发布以来，KDE 团队一直忙于为即将到来的 KDE Plasma 5.23 合并更改和测试新功能。目前 KDE Plasma 5.23 仍在开发中，如下是暂定的时间表。",-1))]),l[22]||(l[22]=r('<h3 id="kde-plasma-5-23-发布时间表" tabindex="-1">KDE Plasma 5.23 发布时间表 <a class="header-anchor" href="#kde-plasma-5-23-发布时间表" aria-label="Permalink to “KDE Plasma 5.23 发布时间表”">​</a></h3><p>KDE Plasma 5.23 将于 2021 年 10 月 7 日发布，以下是时间表：</p><ul><li>Beta 公测 – 2021 年 9 月 16 日</li><li>最终发布 – 2021 年 10 月 7 日</li></ul><p>正如每个 Plasma 版本更新一样，本次更新也同样承诺对核心 Plasma Shell 和 KDE 应用进行大幅更改、代码清理、性能改进、数百个 bug 修复、Wayland 优化等。我们在本篇文章中收集了一些重要的功能，让你对即将发布的新功能有基本了解。下面就让我们看看。</p><h3 id="kde-plasma-5-23-–-新功能" tabindex="-1">KDE Plasma 5.23 – 新功能 <a class="header-anchor" href="#kde-plasma-5-23-–-新功能" aria-label="Permalink to “KDE Plasma 5.23 – 新功能”">​</a></h3><ul><li>本次版本更新基于 Qt 5.15 版本，KDE 框架 5.86 版本。</li></ul><h4 id="plasma-shell-和应用程序更新" tabindex="-1">Plasma Shell 和应用程序更新 <a class="header-anchor" href="#plasma-shell-和应用程序更新" aria-label="Permalink to “Plasma Shell 和应用程序更新”">​</a></h4><ul><li>本次 KDE Plasma 的 Kickoff 程序启动器将有大幅更新，包括 bug 修复、减少内存占用、视觉更新、键鼠导航优化。</li><li>Kickoff 程序启动器菜单允许使用固定按钮固定在桌面上，保持开启状态。</li><li>Kickoff 的标签不会在你滚动时切换（从应用标签到位置标签）。</li><li>Kickoff 里可以使用 <code>CTRL+F</code> 快捷键直接聚焦到搜索栏。</li><li>Kickoff 中的操作按钮（如关机等）可以设置为仅显示图标。</li><li>现在可以针对所有 Kickoff 项目选择使用网格或列表视图（而不仅仅局限于收藏夹）。</li></ul><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/New-Kickoff-Options-in-KDE-Plasma-5.23.jpeg" alt="KDE Plasma 5.23 中 Kickoff 程序启动器新增的选项"></p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/Changes-in-kickoff.jpeg" alt="Kickoff 程序启动器的更改"></p><ul><li>新增基于 QML 的全新概览视图（类似 GNOME 3.38 的工作区视图），用于展示所有打开的窗口（详见如下视频）。目前我找不到关于此合并请求的更多详情，而且这个新视图也很不稳定。</li></ul><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/New-Overview-effect-in-KDE-Plasma-5.23.mp4" alt=""></p><p><em>视频作者：KDE 团队</em></p><ul><li>该概览效果将替代现有的“展现窗口”特效和“虚拟桌面平铺网格”特效（计划中）。</li><li>未连接触控板时将展示更易察觉的“未找到触摸板”提示。</li><li>“电源配置方案”设置现在呈现于 Plasma UI（电池和亮度窗口）中。电源配置方案功能从 Linux 内核 5.12 版本开始已经登陆戴尔和联想的笔记本电脑了。因此，如果你拥有这些品牌的较新款笔记本电脑，你可以将电源配置方案设置为高性能或省电模式。<em>[注：Fedora 35（很大可能）会在 GNOME 41 中增加该功能]</em></li></ul><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/New-power-profiles.jpeg" alt="新的“电源配置方案”设置"></p><ul><li>如果你有多屏幕设置，包括垂直和横向屏幕，那么登录屏幕现在可以正确同步和对齐。这个功能的需求度很高。</li><li>新的 Breeze 主题预计会有风格上的更新。</li><li>如前序版本一样，预计会有全新的壁纸（目前壁纸大赛仍在进行中）。</li><li>新增当硬件从笔记本模式切换到平板模式时是否缩放系统托盘图标的设置。</li><li>你可以选择在登录时的蓝牙状态：总是启用、总是禁用、记住上一次的状态。该状态在版本升级后仍可保留。</li><li>用户现在可以更改传感器的显示名称。</li><li>Breeze 风格的滚动条现在比之前版本的更宽。</li><li>Dolphin 文件管理器提供在文件夹前之前优先显示隐藏文件的新选项。</li><li>你现在可以使用 <code>DEL</code> 键删除剪贴板弹窗中选中的项目。</li><li>KDE 现在允许你直接从 Plasma 桌面，向 store.kde.org 提交你制作的图标和主题。</li></ul><h4 id="wayland-更新" tabindex="-1">Wayland 更新 <a class="header-anchor" href="#wayland-更新" aria-label="Permalink to “Wayland 更新”">​</a></h4><ul><li>在 Wayland 会话中，运行程序时光标旁也会展示图标反馈动画。</li><li>现在可以从通知中复制文字。</li><li>中键单击粘贴功能现在可以在 Wayland 和 XWayland 应用程序中正常使用。</li></ul><p>请务必牢记，每个版本都有数以百计的 bug 修复和改进。本文仅仅包括了我收集的表面层次的东西。因此，如果想了解应用程序和 Plasma Shell 的变更详情，请访问 GitLab 或 KDE Planet 社区。</p><h3 id="不稳定版本下载" tabindex="-1">不稳定版本下载 <a class="header-anchor" href="#不稳定版本下载" aria-label="Permalink to “不稳定版本下载”">​</a></h3><p>你现在可以通过下方的链接下载 KDE neon 的不稳定版本来体验上述全部功能。直接下载 .iso 文件，然后安装测试即可。请务必在发现 bug 后及时反馈。该不稳定版本不适合严肃场合及生产力设备使用。</p>',21)),e("ul",null,[e("li",null,[i(t,{href:"https://neon.kde.org/download"},{default:s(()=>[...l[3]||(l[3]=[a("下载 KDE neon 不稳定版本",-1)])]),_:1})])]),l[23]||(l[23]=e("h3",{id:"结束语",tabindex:"-1"},[a("结束语 "),e("a",{class:"header-anchor",href:"#结束语","aria-label":"Permalink to “结束语”"},"​")],-1)),l[24]||(l[24]=e("p",null,"KDE Plasma 5.23 每次发布都在改进底层、增加新功能。虽然这个版本不是大更新，但一切优化、改进最终都将累积成稳定性、适应性和更好的用户体验。当然，还有更多的 Wayland 改进（讲真，Wayland 兼容看上去一直都处在“正在进行中”的状态 - 就像十年过去了，却还在制作那样。当然这是另一个话题了）。",-1)),l[25]||(l[25]=e("p",null,"再会。",-1)),l[26]||(l[26]=e("hr",null,null,-1)),e("p",null,[l[5]||(l[5]=a("via: ",-1)),i(t,{href:"https://www.debugpoint.com/2021/08/kde-plasma-5-23/"},{default:s(()=>[...l[4]||(l[4]=[a("https://www.debugpoint.com/2021/08/kde-plasma-5-23/",-1)])]),_:1})]),e("p",null,[l[10]||(l[10]=a("作者：",-1)),i(t,{href:"https://www.debugpoint.com/author/admin1/"},{default:s(()=>[...l[6]||(l[6]=[a("Arindam",-1)])]),_:1}),l[11]||(l[11]=a(" 选题：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:s(()=>[...l[7]||(l[7]=[a("lujun9972",-1)])]),_:1}),l[12]||(l[12]=a(" 译者：",-1)),i(t,{href:"https://github.com/imgradeone"},{default:s(()=>[...l[8]||(l[8]=[a("imgradeone",-1)])]),_:1}),l[13]||(l[13]=a(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:s(()=>[...l[9]||(l[9]=[a("wxy",-1)])]),_:1})]),e("p",null,[l[16]||(l[16]=a("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...l[14]||(l[14]=[a("LCTT",-1)])]),_:1}),l[17]||(l[17]=a(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:s(()=>[...l[15]||(l[15]=[a("Linux中国",-1)])]),_:1}),l[18]||(l[18]=a(" 荣誉推出",-1))])])}const k=n(d,[["render",u]]);export{b as __pageData,k as default};
